// attack_nexus.rs:31~52. 인라인되어 사라진 것: Position::as_index(entity.rs:580), MapDef::fountain(map_def.rs:234),
// Option::unwrap(option.rs:1010), bumpalo Vec::is_empty/len(vec.rs:1635/1616)
fn sub_plan(self: &AttackNexusPlan, version, rnd, player: &PlayerState, data: &OperationData, _team_plan, _debug) -> SubPlan {
  // ---- L36 : 이 플레이어의 챔피언 엔티티 얻기
  let team = player.info.team;                          // +0x930, usize
  if team >= 2 { panic_bounds_check(team, 2) }          // player_champion 바깥 배열 길이 2
  let pos  = player.info.position as u32;               // +0x9c0, !range [0,5) — as_index 인라인
  let champ: &Entity = data.cache.player_champion[team][pos].unwrap();  // cache+0x1e0, None 이면 unwrap_failed

  // ---- L37 : 자기 팀 분수대 사각형 (MapDef::fountain(team) 인라인)
  let map = data.context.map;                           // data+0x8 -> GameContext+0x20
  let f   = &map.fountains[team];                       // MapDef+0x6d70 + 32*team
  let (lx, ly, rx, ry) = (f[0], f[1], f[2], f[3]);      // +0x0, +0x8, +0x10, +0x18

  // ---- L38 : is_in_heal_area — 분수대 사각형 안인가 (부호 없는 비교)
  let is_in_heal_area = champ.x >= lx && champ.x <= rx   // 0x660: uge lx && ule rx
                     && champ.y >= ly && champ.y <= ry;  // 0x668: !(ult ly) && !(ugt ry)

  // ---- L41 : 분수대 안이고 아직 풀피가 아니면 계속 회복
  if is_in_heal_area && champ.hp < champ.stat_cached.hp {  // 0x670 ult 0x628
      return SubPlan::Recall(..);                          // tag = 5
  }

  // ---- L45 : 적 팀 쌍둥이 포탑이 남아 있는가
  let has_enemy_twin_tower = !data.cache.twin_towers[1 - team].is_empty();  // len(+0x148) != 0

  // ---- L47~48
  if has_enemy_twin_tower {
      return SubPlan::LineDefense(LineDefenseSubPlan {    // tag = 2
          style:              LineStyle::Aggressive,      // ret+0x8 = 0
          line:               self.line,                  // ret+0x9 = self+0x8 (Top0/Mid1/Bottom2)
          minion_action_type: MinionActionType::Push,     // ret+0xa = 2
      });
  }

  // ---- 적 쌍둥이 포탑이 전멸했을 때만 실제로 넥서스를 친다
  SubPlan::AttackNexus(..)                               // tag = 16
}

// 분기 3개가 전부다. 순서: (1) 분수대 회복 → (2) 적 쌍둥이 포탑 생존 → LineDefense(Push) → (3) AttackNexus.
//
// 태그값 확정 근거: DWARF 의 enum2$<SubPlan> 에서 variantN 의 DISCR_EXACT = N+2 이다.
//   variant0 LineDefense=2, variant3 Recall=5, variant14 AttackNexus=16.
//   교차검증: LineDefense 만 페이로드(LineDefenseSubPlan 3B @ +0x8)를 갖고 Recall/AttackNexus 는 ZST 인데,
//   IR 도 tag=2 경로에서만 +0x8/+0x9/+0xa 3바이트를 쓰고 나머지 두 경로는 tag 만 쓴다 — 정확히 일치.
